SELECT WFL.TRADE_ID tradeId,
WFL.WORKFLOW_STATUS tradeStatus, WFL.WORKFLOW_ID workflowId,
#{validStatus_02} tradeStatus, null workflowId,
#{validStatus_03} tradeStatus, null workflowId,
case WFL.TRADE_STATUS when #{TRADE_STATUS_03} then #{validStatus_03} else #{validStatus_02} end as tradeStatus, null workflowId,
WFLDEAL.ENTRUST_ID entrustId, PP.PORTFOLIO_ID portfolioId, PP.PORTFOLIO_NAME portfolioName, WFL.FINPROD_TYPE2 finprodType, WFL.FINPROD_ID finprodId, FINTYPE.TYPE_6 type1,
FINTYPE.TYPE_9 type9, FINTYPE.TYPE_10 type10, FINTYPE.TYPE_11 type11,
FIN.FINPROD_MARKET_ID finprodMarketId, FIN.FINPROD_NAME finprodName, WFL.PS ps, WFL.TRADE_AMT tradeAmt, WFL.CCY ccy, WFL.TRADE_DATE tradeDate, WFL.REMARK remark
FROM TRD_PRODUCT_DEAL WFL LEFT JOIN TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL WFLPA ON WFL.TRADE_ID = WFLPA.TRADE_ID LEFT JOIN PTL_TRADE PT ON IFNULL(WFL.P_TRADE_ID,WFL.TRADE_ID) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID
FROM WFL_TRD_PRODUCT_DEAL WFL LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN WFL_PA_TRD_PRODUCT_DEAL WFLPA ON WFL.TRADE_ID = WFLPA.TRADE_ID LEFT JOIN PTL_PORTFOLIO PP ON WFLDEAL.PORTFOLIO_ID = PP.PORTFOLIO_ID
LEFT JOIN FIN_PRODUCT FIN ON WFL.FINPROD_ID = FIN.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE FINTYPE ON FIN.FINPROD_ID = FINTYPE.FINPROD_ID
PP.INVEST_YESORNO = 'Y' AND WFL.PS in (#{ps_shengou},#{ps_shuhui})
AND FIN.PROFIT_TYPE = #{PROFIT_TYPE}
