FROM TRD_FIN_PRODUCT_DEAL_TOTAL totalDeal left JOIN TRD_PRODUCT_DEAL deal on totalDeal.TOTLE_TRADE_ID=deal.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD WFLDEAL ON deal.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN PTL_PORTFOLIO PP ON totalDeal.PORTFOLIO_ID = PP.PORTFOLIO_ID
