AND FINTYPE.TYPE_6 = #{finprodType}
AND FINTYPE.TYPE_9 = #{type9}
AND FINTYPE.TYPE_10 = #{type10}
AND FINTYPE.TYPE_11 = #{type11}
AND totalDeal.PS = #{ps}
